import fetchWithAuth from '@/utils/fetchWithAuth';
import FloatingSaveButton from '@/components/FloatingSaveButton.vue';
import unsavedSettings from '@/mixins/unsavedSettings';
export default {
  mixins: [unsavedSettings],
  components: {
    FloatingSaveButton
  },
  data() {
    return {
      dedupEnabled: false,
      pruneLoading: false,
      pruneStatus: '',
      dedupLoading: false,
      dedupStatus: '',
      dedupCleanStatus: '',
      settings: {
        telemetry: {},
        randomImageAPI: {},
        cloudflareApiToken: {},
        webDAV: {},
        publicBrowse: {}
      },
      availableChannels: {},
      // 可用渠道列表
      // 加载状态
      loading: true,
      saving: false
    };
  },
  computed: {
    editableSettings() {
      return this.settings;
    },
    // WebDAV 当前渠道类型对应的渠道列表
    webdavChannelList() {
      const channelType = this.settings.webDAV?.uploadChannel;
      return channelType ? this.availableChannels[channelType] || [] : [];
    }
  },
  watch: {
    'settings.webDAV.uploadChannel'() {
      // 切换渠道类型时清空指定的渠道名称
      if (!this.loading && this.settings.webDAV) {
        this.settings.webDAV.channelName = '';
      }
    }
  },
  methods: {
    showReport(title, data) {
      const summary = `扫描 ${data.scanned ?? '-'} / 渠道对象 ${data.realObjects ?? '-'} / 幽灵 ${data.ghosts ?? '-'} / 补录 ${data.addedMissing?.length ?? '-'} / 删除 ${data.deleted?.length ?? '-'}`;
      this.$alert(`<pre style="max-height:400px;overflow:auto;font-size:12px;">${JSON.stringify(data, null, 2)}</pre>`, title, {
        dangerouslyUseHTMLString: true,
        confirmButtonText: '关闭'
      }).catch(() => {});
      return summary;
    },
    async saveDedupSetting(value) {
      this.dedupStatus = '保存中…';
      try {
        const resp = await fetchWithAuth('/api/manage/sysConfig/upload', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            dedup: {
              enabled: value === true
            }
          })
        });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        this.dedupStatus = value ? '已开启' : '已关闭';
        this.$message.success(value ? '内容去重已开启' : '内容去重已关闭');
      } catch (e) {
        this.dedupStatus = '保存失败';
        this.$message.error('去重设置保存失败');
        this.dedupEnabled = !value;
      }
    },
    async pruneGhosts(dryRun) {
      this.pruneLoading = true;
      this.pruneStatus = dryRun ? '扫描中…' : '清理中…';
      try {
        const resp = await fetchWithAuth(`/api/manage/dedup/prune-ghosts${dryRun ? '?dryRun=true' : ''}`, {
          method: 'POST'
        });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        this.pruneStatus = `幽灵 ${data.ghosts ?? 0} / 删除 ${data.deleted?.length ?? 0} / 补录 ${data.addedMissing?.length ?? 0}`;
        if (!dryRun) this.$message.success(`清理完成:删除 ${data.deleted?.length ?? 0} 条幽灵记录`);
      } catch (e) {
        this.pruneStatus = '失败: ' + (e.message || e);
        this.$message.error('幽灵索引清理失败');
      } finally {
        this.pruneLoading = false;
      }
    },
    async dedupExisting(dryRun) {
      this.dedupLoading = true;
      this.dedupCleanStatus = dryRun ? '扫描中…' : '去重中…';
      try {
        const resp = await fetchWithAuth(`/api/manage/dedup/cleanup${dryRun ? '?dryRun=true' : ''}`, {
          method: 'POST'
        });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        this.dedupCleanStatus = `重复组 ${data.duplicateGroups?.length ?? 0} / 删除 ${data.deleted?.length ?? 0}`;
        if (!dryRun) this.$message.success(`去重完成:删除 ${data.deleted?.length ?? 0} 个重复副本`);
      } catch (e) {
        this.dedupCleanStatus = '失败: ' + (e.message || e);
        this.$message.error('存量去重失败');
      } finally {
        this.dedupLoading = false;
      }
    },
    async saveSettings() {
      if (this.saving) return;
      const submitted = JSON.parse(JSON.stringify(this.settings));
      this.saving = true;
      try {
        const response = await fetchWithAuth('/api/manage/sysConfig/others', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(submitted)
        });
        if (!response.ok) throw new Error(this.$t('floatingSave.failed'));
        this.markSettingsSaved(submitted);
        this.$message.success(this.$t('sysOthers.settingsSaved'));
      } catch {
        this.$message.error(this.$t('floatingSave.failed'));
      } finally {
        this.saving = false;
      }
    },
    async fetchAvailableChannels() {
      try {
        const response = await fetchWithAuth('/api/channels');
        if (response.ok) {
          this.availableChannels = await response.json();
        }
      } catch (error) {
        console.error('Failed to fetch available channels:', error);
      }
    }
  },
  mounted() {
    this.loading = true;
    // 去重开关状态在 upload 设置里
    fetchWithAuth('/api/manage/sysConfig/upload').then(r => r.json()).then(data => {
      this.dedupEnabled = data?.dedup?.enabled === true;
    }).catch(() => {});
    // 获取其它设置
    fetchWithAuth('/api/manage/sysConfig/others').then(response => response.json()).then(async data => {
      this.settings = data;
      await this.$nextTick();
      this.markSettingsSaved();
    }).finally(() => {
      this.loading = false;
    });
    // 获取可用渠道列表
    this.fetchAvailableChannels();
  }
};